<section class="card card-body"><p><?= $e($listing['total']??0) ?> <?= \App\Support\I18n::html('matching invoices') ?></p><?php if(empty($listing['rows'])): ?><p><?= \App\Support\I18n::html('No invoices match these filters. No fictional sales have been created.') ?></p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th><?= \App\Support\I18n::html('Invoice / date') ?></th><th><?= \App\Support\I18n::html('Customer / source') ?></th><th><?= \App\Support\I18n::html('Total LKR') ?></th><th><?= \App\Support\I18n::html('Outstanding LKR') ?></th><th><?= \App\Support\I18n::html('Status') ?></th></tr></thead><tbody><?php foreach($listing['rows'] as $r): ?><tr><td><a href="<?= $url($base.'/'.$r['id']) ?>"><?= $e($r['invoice_number']) ?></a><small class="d-block"><?= $e($r['business_date']) ?></small></td><td><?= $e($r['customer']['shop_name']) ?><small class="d-block"><?= $e($r['rep_name_snapshot']) ?></small></td><td><?= $e($r['grand_total']) ?></td><td><?= $e($r['outstanding']) ?></td><td><?= $e(\App\Support\I18n::text($r['validity']).' / '.\App\Support\I18n::text($r['payment_status'])) ?><?php require APP_ROOT.'/app/Views/invoice-document-actions.php'; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?><?php if(($listing['pages']??1)>1): ?><nav aria-label="<?= \App\Support\I18n::html('Invoice pages') ?>"><?php foreach([-1=>'Previous',1=>'Next'] as $d=>$label): $target=$listing['page']+$d;if($target<1||$target>$listing['pages'])continue;$query=$_GET;$query['page']=(string)$target; ?><a class="me-3" href="<?= $url($base.'?'.http_build_query($query)) ?>"><?= \App\Support\I18n::html($label) ?></a><?php endforeach; ?><?= \App\Support\I18n::html('Page') ?> <?= $e($listing['page']) ?> / <?= $e($listing['pages']) ?></nav><?php endif; ?></section>
<?php endif; ?></main><?php require APP_ROOT.'/app/Views/workspace-footer.php'; ?></body></html>
